// Processar resultado da análise de imagem
const analysis = $json.content || '';

// Detectar receita com mais precisão
const receiptKeywords = [
  'RECEITA', 'MÉDICA', 'OFTALMOLOGISTA', 'OPTOMETRISTA',
  'OD:', 'OE:', 'ESF', 'CIL', 'EIXO', 'DNP', 'DP',
  'MIOPIA', 'HIPERMETROPIA', 'ASTIGMATISMO', 'PRESBIOPIA',
  'GRAU', 'DIOPTRIA', 'ADD', 'ADIÇÃO'
];

const isReceipt = receiptKeywords.some(keyword => 
  analysis.toUpperCase().includes(keyword)
);

// Adicionar contexto do estado do fluxo
const conversationState = {
  isReceipt,
  messageType: isReceipt ? "medical_receipt" : "image",
  needsPhotosensitiveQuestion: isReceipt,
  timestamp: new Date().toISOString()
};

let processedMessage;
if (isReceipt) {
  processedMessage = `RECEITA DETECTADA: ${analysis}`;
} else {
  processedMessage = `Descrição da imagem enviada: ${analysis}`;
}

return {
  ...conversationState,
  processedMessage,
  originalAnalysis: analysis
};

// Armazenar estado da conversa com detecção de intervenção humana
const phone = $('Webhook').item.json.body.phone;
const message = $json.MESSAGE || '';
const fromMe = $('Webhook').item.json.body.fromMe;
const fromApi = $('Webhook').item.json.body.fromApi;

// Detectar se é mensagem humana
const isHumanMessage = fromMe === true && fromApi === false;

// Detectar fluxo baseado na mensagem
let currentFlow = null;
let currentStep = null;

// Palavras-chave para detecção de fluxo
const glassesKeywords = ['óculos', 'grau', 'receita', 'miopia', 'hipermetropia', 'astigmatismo'];
const contactsKeywords = ['lentes de contato', 'lentes coloridas'];
const storeKeywords = ['endereço', 'loja física', 'onde fica', 'localização'];

// Só detecta fluxo se não for mensagem humana
if (!isHumanMessage) {
  if (glassesKeywords.some(kw => message.toLowerCase().includes(kw))) {
    currentFlow = 'glasses';
    currentStep = 'asking_receipt';
  } else if (contactsKeywords.some(kw => message.toLowerCase().includes(kw))) {
    currentFlow = 'contacts';
    currentStep = 'asking_type';
  } else if (storeKeywords.some(kw => message.toLowerCase().includes(kw))) {
    currentFlow = 'store_info';
    currentStep = 'provided_info';
  }
}

// Detectar se é receita
const hasReceipt = message.includes('RECEITA DETECTADA');

// Construir estado com informação de intervenção humana
const state = {
  currentFlow,
  currentStep,
  hasReceipt,
  wantsPhotosensitive: null,
  lastInteraction: new Date().toISOString(),
  messageCount: 1,
  phone,
  hasHumanIntervention: isHumanMessage,
  lastHumanInteraction: isHumanMessage ? new Date().toISOString() : null,
  humanInterventionEnd: isHumanMessage ? new Date(Date.now() + $('ALTERE ISSO').item.json['HUMAN-INTERVENTION-WINDOW'] * 60 * 1000).toISOString() : null
};

return { state, shouldStore: true, isHumanMessage };

// DETECT HUMAN INTERVENTION AND ABANDONMENT
// Este node detecta intervenção humana e abandono de conversa

const phone = $('Webhook').item.json.body.phone;
const fromMe = $('Webhook').item.json.body.fromMe;
const fromApi = $('Webhook').item.json.body.fromApi;
const stateData = $('GET CONVERSATION STATE').item.json;
const message = $json.MESSAGE || '';

// Configurações
const abandonmentTime = $('ALTERE ISSO').item.json['ABANDONMENT-TIME'] || 30;
const humanWindowTime = $('ALTERE ISSO').item.json['HUMAN-INTERVENTION-WINDOW'] || 4320;
const takeoverKeywords = $('ALTERE ISSO').item.json['HUMAN-TAKEOVER-KEYWORDS'] || [];

let state;
try {
  state = stateData.value ? JSON.parse(stateData.value) : null;
} catch (e) {
  state = null;
}

// 1. DETECTAR MENSAGEM HUMANA ATUAL
const isCurrentMessageHuman = fromMe === true && fromApi === false;

// 2. VERIFICAR TIMEOUT HUMANO ATIVO
let hasActiveHumanTimeout = false;
let humanTimeoutRemaining = 0;

if (state && state.humanInterventionEnd) {
  const humanEnd = new Date(state.humanInterventionEnd);
  const now = new Date();

  if (humanEnd > now) {
    hasActiveHumanTimeout = true;
    humanTimeoutRemaining = Math.round((humanEnd - now) / 1000 / 60); // em minutos
  }
}

// 3. ATUALIZAR ESTADO SE NECESSÁRIO
if (isCurrentMessageHuman && state) {
  // Marcar início da intervenção humana
  state.hasHumanIntervention = true;
  state.humanInterventionStart = new Date().toISOString();
  state.humanInterventionEnd = new Date(Date.now() + humanWindowTime * 60 * 1000).toISOString();
  state.lastHumanMessage = message;

  // Retornar com flag para pausar bot
  return {
    shouldReset: false,
    shouldPauseBot: true,
    isHumanIntervention: true,
    humanTimeoutMinutes: humanWindowTime,
    message: "Intervenção humana detectada - Bot pausado",
    state
  };
}

// 4. SE HÁ TIMEOUT HUMANO ATIVO, NÃO FAZER NADA
if (hasActiveHumanTimeout) {
  return {
    shouldReset: false,
    shouldPauseBot: true,
    hasActiveHumanTimeout: true,
    humanTimeoutRemaining,
    message: `Bot pausado - Consultor humano ativo (${humanTimeoutRemaining} minutos restantes)`,
    state
  };
}

// 5. VERIFICAR ABANDONO NORMAL (só se não há intervenção humana)
if (!state) {
  return { 
    shouldReset: false, 
    state: null,
    message: "Sem estado anterior - Nova conversa"
  };
}

const lastMessageTime = new Date(state.lastInteraction);
const now = new Date();
const minutesSinceLastMessage = (now - lastMessageTime) / 1000 / 60;

// 6. DETECTAR PALAVRAS DE TAKEOVER
const hasTakeoverKeyword = takeoverKeywords.some(keyword => 
  message.toLowerCase().includes(keyword.toLowerCase())
);

if (hasTakeoverKeyword) {
  // Configurar timeout humano
  state.hasHumanIntervention = true;
  state.humanInterventionStart = new Date().toISOString();
  state.humanInterventionEnd = new Date(Date.now() + humanWindowTime * 60 * 1000).toISOString();

  return {
    shouldReset: false,
    shouldPauseBot: true,
    detectedTakeover: true,
    message: "Palavras de transferência detectadas - Bot pausado",
    state
  };
}

// 7. VERIFICAR ABANDONO
if (minutesSinceLastMessage > abandonmentTime) {
  // Verificar se houve intervenção humana recente
  if (state.humanInterventionEnd) {
    const humanEndTime = new Date(state.humanInterventionEnd);
    const timeSinceHumanIntervention = (now - humanEndTime) / 1000 / 60;

    // Se a intervenção humana terminou há pouco tempo, dar mais tempo
    if (timeSinceHumanIntervention < 60) { // 1 hora após fim da intervenção
      return {
        shouldReset: false,
        recentHumanIntervention: true,
        timeSinceHumanIntervention,
        message: "Intervenção humana recente - Estendendo timeout",
        state
      };
    }
  }

  // Resetar conversa
  return {
    shouldReset: true,
    abandonmentDetected: true,
    minutesSinceLastMessage,
    message: "Oi! Vi que você ficou um tempinho sem responder. Vamos começar de novo? 😊",
    state
  };
}

// 8. CONTINUAR NORMALMENTE
return { 
  shouldReset: false,
  shouldPauseBot: false,
  state,
  minutesSinceLastMessage,
  message: "Conversa ativa - Bot continua"
};

// Validar resposta do Agent
const response = $json.output || '';
const validMarkers = [
  '[BOTÕES:APRESENTAÇÃO]',
  '[BOTÕES:TEM_RECEITA]',
  '[BOTÕES:FOTOSSENSÍVEIS]',
  '[BOTÕES:TIPO_LENTE]',
  '[BOTÕES:COR_LENTE]',
  '[BOTÕES:SIM_NAO]'
];

// Verificar se há marcadores válidos
const hasValidMarker = validMarkers.some(marker => 
  response.includes(marker)
);

// Verificar se a resposta está vazia ou muito longa
const isValidLength = response.length > 10 && response.length < 1000;

// Se inválido, usar resposta padrão
if (!isValidLength) {
  return {
    output: "Desculpe, tive um problema. Um consultor vai te ajudar! 💙",
    isValid: false
  };
}

return {
  output: response,
  isValid: true,
  hasButtons: hasValidMarker
};

// Rastrear analytics
const startTime = Date.now();
const phone = $('Webhook').item.json.body.phone;
const state = $('DETECT HUMAN INTERVENTION & ABANDONMENT').item.json.state;
const response = $json;
const humanInterventionStatus = $('DETECT HUMAN INTERVENTION & ABANDONMENT').item.json;

const analyticsData = {
  phone,
  timestamp: new Date().toISOString(),
  flowType: state?.currentFlow || 'unknown',
  stepReached: state?.currentStep || 'initial',
  hasButtons: response.hasButtons || false,
  responseTime: Date.now() - startTime,
  isSuccessful: response.isValid || false,
  responseLength: response.output?.length || 0,
  abandonmentRisk: false,
  errorCount: parseInt($('GET ERROR COUNT').item.json.value || '0'),
  hasHumanIntervention: humanInterventionStatus.shouldPauseBot || false,
  humanInterventionType: humanInterventionStatus.isHumanIntervention ? 'direct' : 
                         humanInterventionStatus.detectedTakeover ? 'keyword' : 
                         humanInterventionStatus.hasActiveHumanTimeout ? 'active' : 'none'
};

// Preparar para salvar em planilha
return analyticsData;

